from pathlib import Path
import json,time
base=Path.home()/".local/share/prediction-project-executor/campaigns/FULL-A2Z-LIVE-20261004-V4"
task="A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2"
expected_checkpoint="runs/A2Z-V4-ASTRA-PREBUILD-DIRECT-20261007-R4P2-5-9a8e982f"
expected_retry=1791401303.2864633
result=base/"model_results"/(task+".json")
if result.is_file():
    raise SystemExit(10)
models=base/"models"
state=None
for name in ("CONTINUATION.json","STATE.json"):
    p=models/name
    if not p.is_file():
        continue
    try:
        o=json.loads(p.read_text(encoding="utf-8"))
    except Exception:
        continue
    if isinstance(o,dict) and o.get("task_id")==task:
        state=o
        break
if not isinstance(state,dict):
    raise SystemExit(20)
if state.get("state")!="PAUSED_USAGE_LIMIT":
    raise SystemExit(21)
if state.get("next_action")!="resume_same_task":
    raise SystemExit(22)
if state.get("checkpoint")!=expected_checkpoint:
    raise SystemExit(24)
if state.get("attempt") not in (None,5):
    raise SystemExit(25)
now=time.time()
if now<expected_retry:
    time.sleep(expected_retry-now+1)
raise SystemExit(0)
